'use strict';
// Tokens stay in HttpOnly cookies. CSRF material is memory-only. No innerHTML is used.
const $ = id => document.getElementById(id);
const state = {csrf: '', user: null, events: [], devices: [], cursor: '', next: null, page: 1, settings: null, busy: false};
function node(tag, text, cls) { const n=document.createElement(tag); if(text!==undefined)n.textContent=String(text); if(cls)n.className=cls; return n; }
function message(text, error=false) { const n=$('app-message'); n.textContent=text; n.className=text ? error?'error':'success':''; }
function date(value) { if(!value)return 'Never'; const d=new Date(typeof value==='number'?value*1000:value); return Number.isNaN(d.valueOf())?'Unavailable':d.toLocaleString(); }
function signedOut(){state.csrf='';state.user=null;state.events=[];state.devices=[];$('dashboard').hidden=true;$('login').hidden=false;$('dev-key').value='';$('pair-code').textContent='';$('pair-result').hidden=true;}
async function api(path, options={}) {
  const headers={'Accept':'application/json',...options.headers};
  if(options.body!==undefined){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  if(options.method && options.method!=='GET')headers['X-CSRF-Token']=state.csrf;
  let response;
  try{response=await fetch('/api'+path,{...options,headers,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000)});}
  catch{throw new Error('Cloud service unavailable. Local Sentinel authorization continues independently.');}
  if(response.status===401){signedOut();throw new Error('Sign-in required or session expired.');}
  if(!response.ok){const safe={403:'Request rejected. Refresh your session and check account permissions.',404:'Record unavailable.',409:'Request cannot be completed in its current state.',413:'Request exceeds the service size limit.',429:'Cloud rate or storage limit reached. Retry later; local protection continues.',503:'Cloud service unavailable or not configured.'};throw new Error(safe[response.status]||`Request failed (HTTP ${response.status}).`);}
  try{return await response.json();}catch{throw new Error('Invalid service response. No account operation was assumed successful.');}
}
async function guarded(action){if(state.busy)return;state.busy=true;document.body.classList.add('busy');message('');try{await action();}catch(e){message(e.message,true);$('connection').textContent='Refresh failed · displayed records may be stale';$('connection').className='status offline';}finally{state.busy=false;document.body.classList.remove('busy');}}
function view(name){document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));for(const name2 of ['overview','events','devices','settings'])$('view-'+name2).hidden=name!==name2;}
function renderEvents(){const box=$('event-list');box.replaceChildren();const filter=$('device-filter').value;const events=state.events.filter(e=>!filter||e.device_id===filter);if(!events.length){box.append(node('div','No events on this page match the current filters.','empty'));}else{const scroll=node('div',undefined,'table-scroll');const table=node('table');const head=node('thead');const row=node('tr');for(const h of ['Time','Operation','Decision','Executed','Reason','Device'])row.append(node('th',h));head.append(row);table.append(head);const body=node('tbody');for(const e of events){const r=node('tr');r.append(node('td',date(e.timestamp)),node('td',e.operation));const decision=node('td');decision.append(node('span',e.decision,'badge '+(['ALLOW','DENY','REQUIRE_APPROVAL'].includes(e.decision)?e.decision:'')));r.append(decision,node('td',e.executed?'Yes':'No'),node('td',e.reason_code));const device=state.devices.find(d=>d.id===e.device_id);r.append(node('td',device?device.name:e.device_id));body.append(r);}table.append(body);scroll.append(table);box.append(scroll);}$('page-status').textContent=`Page ${state.page} · ${events.length} visible / ${state.events.length} loaded`;$('next-page').disabled=!state.next;$('first-page').disabled=state.page===1;}
function bars(id, records){const host=$(id);host.replaceChildren();if(!records.length){host.append(node('p','No synchronized events in the loaded page.','caption'));return;}const maximum=Math.max(...records.map(r=>r[1]),1);for(const [label,count] of records){const row=node('div',undefined,'bar');row.append(node('span',label));const meter=node('meter');meter.min=0;meter.max=maximum;meter.value=count;meter.setAttribute('aria-label',`${label}: ${count} events`);row.append(meter,node('span',count));host.append(row);}}
function renderOverview(){const days=Object.create(null),ops=Object.create(null),reasons=Object.create(null);for(const e of state.events){const d=new Date(typeof e.timestamp==='number'?e.timestamp*1000:e.timestamp);const day=Number.isNaN(d.valueOf())?'Unknown':d.toISOString().slice(0,10);days[day]=(days[day]||0)+1;ops[e.operation]=(ops[e.operation]||0)+1;reasons[e.reason_code]=(reasons[e.reason_code]||0)+1;}bars('timeline',Object.entries(days).sort());bars('categories',Object.entries(ops).sort((a,b)=>b[1]-a[1]));const host=$('reasons');host.replaceChildren();const explanations={authorized:'The gateway permitted this request.',denied:'The task did not authorize this operation or resource.',policy_blocked:'A local policy or provenance restriction blocked the action.',invalid:'The request or approval was invalid.',execution_failed:'Execution did not complete.',unknown:'Consult the private local audit for details.',allowed:'The gateway permitted this request.',not_authorized:'The task did not authorize this operation or resource.',protected_flow_blocked:'Experimental provenance rules blocked a subsequent sink.',approval_required:'A local, authenticated approval is required.',sensitive_resource:'A sensitive-resource restriction applied.',expired:'The authority expired.'};for(const [reason,count]of Object.entries(reasons)){const p=node('p');p.append(node('code',reason),document.createTextNode(` · ${count} · ${explanations[reason]||'See the local audit and runtime reason-code documentation.'}`));host.append(p);}if(!Object.keys(reasons).length)host.append(node('p','Reason codes will appear when events are synchronized.','caption'));}
function renderDevices(){const host=$('device-list');host.replaceChildren();const filter=$('device-filter');const selected=filter.value;filter.replaceChildren(new Option('All devices',''));if(!state.devices.length)host.append(node('div','No linked devices. Create a code below to enroll your first installation.','empty'));for(const d of state.devices){filter.append(new Option(d.name,d.id));const card=node('article',undefined,'device');const content=node('div');content.append(node('h3',d.name),node('p',`Device ID: ${d.id}`),node('p',`Last successful contact: ${date(d.last_seen_at)} · ${d.revoked_at?'Revoked':'Connectivity unknown'}`));card.append(content);const button=node('button',d.revoked_at?'Revoked':'Revoke device','danger');button.disabled=Boolean(d.revoked_at);button.onclick=()=>guarded(async()=>{if(!confirm('Revoke this device credential? Future uploads will be rejected. Local task permissions are unchanged.'))return;await api('/devices/'+encodeURIComponent(d.id)+'/revoke',{method:'POST',body:{}});await refresh();message('Device credential revoked.');});card.append(button);host.append(card);}filter.value=selected;}
async function loadEvents(){const q=new URLSearchParams({limit:'50'});if(state.cursor)q.set('cursor',state.cursor);if($('decision').value)q.set('decision',$('decision').value);const data=await api('/events?'+q);if(!Array.isArray(data.events))throw new Error('Invalid events response.');state.events=data.events;state.next=data.next_cursor||null;renderEvents();renderOverview();}
async function refresh(){const [summary,devices,settings]=await Promise.all([api('/summary'),api('/devices'),api('/settings')]);if(!Array.isArray(devices.devices))throw new Error('Invalid devices response.');state.devices=devices.devices;state.settings=settings;for(const [id,key]of [['total','total'],['allow','allow'],['deny','deny'],['approval','require_approval']])$('metric-'+id).textContent=Number.isSafeInteger(summary[key])?summary[key]:'Unavailable';$('sync-enabled').checked=settings.sync_enabled===true;$('retention').textContent=`Event retention: ${settings.retention_days} days. Expired records are excluded from retrieval.`;$('sync-summary').textContent=`Cloud ingestion is ${settings.sync_enabled?'enabled':'disabled'}. ${state.devices.filter(d=>!d.revoked_at).length} non-revoked device(s). Device contact is historical; this dashboard does not claim a persistent online connection.`;renderDevices();await loadEvents();$('connection').className='status';$('connection').textContent='Updated '+new Date().toLocaleTimeString();}
async function session(){const data=await api('/session');if(!data.user||typeof data.csrf_token!=='string')throw new Error('Invalid session response.');state.user=data.user;state.csrf=data.csrf_token;$('login').hidden=true;$('dashboard').hidden=false;$('account-label').textContent=`Signed in as ${data.user.login}`;await refresh();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
$('refresh').onclick=()=>guarded(refresh);
$('login-form').onsubmit=e=>{e.preventDefault();const key=$('dev-key').value;$('dev-key').value='';guarded(async()=>{await api('/dev/login',{method:'POST',body:{key,identity:$('dev-identity').value}});await session();});};
$('logout').onclick=()=>guarded(async()=>{await api('/logout',{method:'POST',body:{}});signedOut();message('Signed out.');});
$('decision').onchange=()=>guarded(async()=>{state.cursor='';state.page=1;await loadEvents();});$('device-filter').onchange=renderEvents;
$('next-page').onclick=()=>guarded(async()=>{if(!state.next)return;const old=state.cursor;state.cursor=state.next;try{await loadEvents();state.page++;renderEvents();}catch(e){state.cursor=old;throw e;}});
$('first-page').onclick=()=>guarded(async()=>{state.cursor='';state.page=1;await loadEvents();});
$('pair-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const data=await api('/devices/pair',{method:'POST',body:{name:$('device-name').value}});$('pair-code').textContent=data.pairing_code;$('pair-expiry').textContent='One-time enrollment code. Expires '+date(data.expires_at)+'. Do not share it or include it in screenshots.';$('pair-result').hidden=false;setTimeout(()=>{$('pair-code').textContent='';$('pair-result').hidden=true;},300000);});};
$('hide-code').onclick=()=>{$('pair-code').textContent='';$('pair-result').hidden=true;};
$('save-sync').onclick=()=>guarded(async()=>{await api('/settings',{method:'PATCH',body:{sync_enabled:$('sync-enabled').checked}});await refresh();message('Cloud synchronization consent updated. Local consent is still required.');});
$('delete-events').onclick=()=>guarded(async()=>{if(!confirm('Permanently delete your synchronized cloud events?'))return;await api('/events',{method:'DELETE',body:{}});state.cursor='';state.page=1;await refresh();message('Cloud events deleted. Local audit records are unchanged.');});
$('delete-account').onclick=()=>guarded(async()=>{if(prompt('Type DELETE to permanently delete this cloud account and its records.')!=='DELETE')return;await api('/account',{method:'DELETE',body:{}});signedOut();message('Cloud account deleted.');});
if(['127.0.0.1','localhost','[::1]'].includes(location.hostname))$('dev-login').hidden=false;
// No background mutations or polling of device commands exist.
session().catch(e=>{if(!e.message.startsWith('Sign-in required'))message(e.message,true);});
